mapper.select:
SELECT p.*, d.name AS device_name, d.device_no, u.real_name AS inspector_name
FROM inspection_plan p
LEFT JOIN device d ON p.device_id = d.id
LEFT JOIN user u ON p.inspector_id = u.id

    AND p.device_id = #{deviceId}

ORDER BY p.id DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE inspection_plan
device_id = #{deviceId}, inspector_id = #{inspectorId}, cycle_days = #{cycleDays}, next_inspection_date = #{nextInspectionDate}, status = #{status},
WHERE id = #{id}
